const SKILL_PLAYBOOKS: Record<string, string | ((ctx: PlaybookCtx) => string)> = {
  'prompting-guides': (ctx) => {
    const imageOn = skillOn(ctx.skills, 'image-generation')
    const videoOn = skillOn(ctx.skills, 'video-production')
    const usable = usableCreateModels(true).filter(m => !m.disabled && m.guide
      && ((m.kind === 'image' && imageOn) || (m.kind === 'video' && videoOn)))
    if (!usable.length) return 'No prompting guides available for the enabled media kinds.'
    return [
      'PROMPTING GUIDES (distilled from each model\'s official fal guide — write prompts by the target model\'s rules, they differ sharply):',
      ...usable.map(m => `- ${m.id}: ${m.guide}`),
    ].join('\n')
  },
  'graphic-design': GD,
  'color-theory': COLOR_THEORY,
  'lighting-design': LIGHTING,
  'style-lexicon': STYLE_LEXICON,
  'photography-craft': PHOTOGRAPHY,
  'materials-surfaces': MATERIALS,
  'figure-anatomy': ANATOMY,
  'photoshop': PHOTOSHOP,
  'sketching': SKETCHING,
  'ad-creative-director': AD_DIRECTOR,
  'ugc-content': UGC,
  'product-photography': PRODUCT_SHOTS,
  'brand-kit': BRAND_KIT,
  'cinematic-direction': CINEMATIC,
  'script-storyboard': STORYBOARD,
  'montage-sequencing': MONTAGE,
  'movie-production': MOVIE_PRODUCTION,
  'cartoon-anime': CARTOON,
  'look-transfer': [LOOK_TRANSFER, LOOK_RECIPES].join('\n'),
  'character-design': CHARACTER_DESIGN,
  'character-consistency': CHARACTER,
  'character-fusion': CHARACTER_FUSION,
  'typography-poster': TYPOGRAPHY,
  'dataset-ops': DATASET_OPS,
  'platform-formats': FORMATS,
  'thumbnail-design': THUMBNAIL,
  'copywriting-captions': COPYWRITING,
}

export function getPlaybook(id: string, ctx: PlaybookCtx): string | null {
  const pb = SKILL_PLAYBOOKS[id]
  if (!pb) return null
  return typeof pb === 'function' ? pb(ctx) : pb
}
